import React from 'react';
import { chakra, Drawer, DrawerOverlay, DrawerContent, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';

const ZIMM_DRAWER_RECIPE = 'ZimmDrawer';

export type ZimmDrawerSize = 'large' | 'small' | 'mobile';

type ZimmDrawerBaseProps = {
  /** Whether the drawer is open. */
  isOpen: boolean;
  /** Called on backdrop click, Escape, and the close button (all via Chakra's Drawer). */
  onClose: () => void;
  /** Desktop width variant. Collapses to the mobile treatment below the tablet breakpoint
   *  regardless of which value is chosen — see zimmDrawer.css.ts. */
  size: ZimmDrawerSize;
  children: React.ReactNode;
};

type ZimmDrawerProps = ZimmDrawerBaseProps &
  ({ labelledBy: string; 'aria-label'?: never } | { labelledBy?: never; 'aria-label': string });

/**
 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Large/Small/Mobile width
 * variant, built on Chakra's Drawer primitive (focus trap, initial focus, focus restore,
 * body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not hand-rolled).
 * Owns the close button only — no header/tab content of its own, so both a tabbed header
 * (ZimmPdpDrawer) and a plain-title header (e.g. a future country/currency selector) can compose
 * on top of it.
 *
 * @param props see ZimmDrawerProps
 */
export const ZimmDrawer = ({ isOpen, onClose, size, children, ...aria }: ZimmDrawerProps) => {
  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });

  return (
    <Drawer isOpen={isOpen} onClose={onClose} placement="right">
      <DrawerOverlay sx={styles.overlay} />
      <DrawerContent aria-labelledby={aria.labelledBy} aria-label={aria['aria-label']} sx={styles.content}>
        <chakra.div sx={styles.closeButton}>
          <ZimmButton variant="icon" icon="close" label="Close" onClick={onClose} />
        </chakra.div>
        {children}
      </DrawerContent>
    </Drawer>
  );
};
