import { breakpoints } from 'app/theme/foundation';

// Figma pdp/drawer: Large = 50% of viewport width, Small = 25% — Tim confirmed (2026-08-27)
// to build Small to the named 25%, not the 27.9% actually measured in the current Figma frame;
// he is flagging that discrepancy to the design team separately.
const WIDTH_LARGE = '50%';
const WIDTH_SMALL = '25%';

// Mobile deliberately leaves a strip of backdrop visible below the panel (SFCC-736 AC 9,
// PO-approved 2026-08-21 — "so a user can easily navigate out"). Figma measured ~78px;
// var(--zimm-scale-5xl) (80px) is the closest named-scale match, kept pending Tim's separate
// design/PO confirmation of the exact value.
const MOBILE_BOTTOM_GAP = 'var(--zimm-scale-5xl)';

// Close-button inset, measured from the pdp/drawer header frames. Small and Mobile share the
// same measured inset (32px/40px) at every width; Large only switches to the wider 48px/64px
// inset at/above the tablet breakpoint — below it, `large`'s variant override doesn't apply and
// the compact baseStyle inset is used instead, which is also how the whole drawer collapses to
// the mobile treatment on a narrow viewport regardless of the chosen `size`.
const INSET_COMPACT = { top: 'var(--zimm-scale-3xl)', right: 'var(--zimm-scale-2xl)' };
const INSET_LARGE = { top: 'var(--zimm-scale-1200)', right: 'var(--zimm-scale-4xl)' };

export const ZimmDrawer = {
  parts: ['overlay', 'content', 'closeButton'],
  baseStyle: {
    // Explicit position/inset rather than relying on Chakra's own built-in `Drawer` overlay
    // styling — confirmed via inspection that it doesn't apply (renders `position: static`,
    // zero size) when the `<Drawer>` isn't given Chakra's own `size` prop, which this component
    // deliberately omits (see maxWidth note below). Owning it here avoids depending on that.
    overlay: {
      position: 'fixed',
      inset: 0,
      background: 'var(--zimm-color-opacity-50)',
      zIndex: 'overlay',
    },
    content: {
      width: '100%',
      // Matches `width` at every step below — Chakra's own `Drawer` theme defaults to
      // `size="xs"` (maxW 20rem) when no `size` prop is passed to `<Drawer>` (deliberate: its
      // fixed size scale has no 50%/25% steps), and that default `maxW` otherwise still caps
      // our own `width` override since we never reset it.
      maxWidth: '100%',
      bottom: MOBILE_BOTTOM_GAP,
      // Header stays fixed; only the content area (ZimmPdpDrawer's own `content` part) scrolls —
      // AC 10, "content area scrolls independently without the tab header scrolling".
      display: 'flex',
      flexDirection: 'column',
      overflow: 'hidden',
    },
    closeButton: INSET_COMPACT,
  },
  variants: {
    large: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_LARGE,
          maxWidth: WIDTH_LARGE,
          bottom: 0,
        },
      },
      closeButton: {
        [`@media (min-width: ${breakpoints.md})`]: INSET_LARGE,
      },
    },
    small: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_SMALL,
          maxWidth: WIDTH_SMALL,
          bottom: 0,
        },
      },
    },
    // No override — the baseStyle above already is the mobile treatment.
    mobile: {},
  },
};

import React, { useCallback, useEffect, useRef, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
import type { ZimmDrawerSize } from 'app/components/ui-kits/atoms/zimmDrawer';

const ZIMM_TABS_RECIPE = 'ZimmTabs';

export type ZimmTabItem = {
  /** Stable id used for activeTabId and the onTabChange callback. */
  id: string;
  /** Visible label — Contentful-driven per tab, so length varies and drives the overflow check. */
  label: string;
};

type ZimmTabsProps = {
  tabs: ZimmTabItem[];
  activeTabId: string;
  onTabChange: (id: string) => void;
  /** Matches the parent ZimmDrawer's size, so header padding stays in sync at every breakpoint. */
  size: ZimmDrawerSize;
  /** Accessible name for the `tablist` itself — WAI-ARIA's Tabs pattern requires one whenever
   *  there's no visible on-page label for the tab list (there isn't one here). The caller's own
   *  dialog `aria-label` is a reasonable value to reuse, per ZimmPdpDrawer. */
  ariaLabel: string;
  /**
   * Shared id prefix this tablist's tab buttons derive their own `id`/`aria-controls` from —
   * `${idPrefix}-tab-${tab.id}` / `${idPrefix}-panel`. The caller (ZimmPdpDrawer) uses the same
   * prefix for its panel's `id`/`aria-labelledby`, so the two stay in sync without either side
   * needing to know the other's internals. Generate with React's `useId()` at the call site so
   * ids are unique even with more than one tabbed drawer mounted at once.
   */
  idPrefix: string;
};

/**
 * Generic tab switcher — a row of tab buttons with width-based overflow: chevrons render only
 * when the next tab doesn't fit in the available width, and scroll the list by one tab per
 * click. Left/Right/Home/End move both focus and selection between tabs (WAI-ARIA tablist
 * "automatic activation" pattern — recommended when, as here, switching panel content has no
 * loading cost: https://www.w3.org/WAI/ARIA/apg/patterns/tabs/), with a roving tabIndex so Tab
 * only stops once, on the active tab, then moves on to the next focusable element outside the
 * tablist. Owns no panel content — a caller pairs the active tab id with its own content switch
 * (see ZimmPdpDrawer).
 *
 * @param props see ZimmTabsProps
 */
export const ZimmTabs = ({ tabs, activeTabId, onTabChange, size, ariaLabel, idPrefix }: ZimmTabsProps) => {
  const styles = useMultiStyleConfig(ZIMM_TABS_RECIPE, { variant: size });
  const listRef = useRef<HTMLDivElement>(null);
  const tabRefs = useRef(new Map<string, HTMLButtonElement>());
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(false);

  const updateOverflow = useCallback(() => {
    const list = listRef.current;
    if (!list) return;
    setCanScrollLeft(list.scrollLeft > 0);
    setCanScrollRight(list.scrollLeft + list.clientWidth < list.scrollWidth - 1);
  }, []);

  // A same-count label swap (Contentful edit, locale switch) changes `scrollWidth` without
  // changing the tablist's own border/content-box dimensions, so ResizeObserver's callback never
  // fires for it — recompute on the labels themselves, not just how many there are.
  const tabsSignature = tabs.map((tab) => `${tab.id}:${tab.label}`).join('|');

  useEffect(() => {
    updateOverflow();
    const list = listRef.current;
    if (!list) return undefined;

    const observer = new ResizeObserver(updateOverflow);
    observer.observe(list);
    list.addEventListener('scroll', updateOverflow);
    return () => {
      observer.disconnect();
      list.removeEventListener('scroll', updateOverflow);
    };
  }, [updateOverflow, tabsSignature]);

  // Move focus to the active tab whenever it changes while focus is already inside the
  // tablist — covers arrow-key navigation; a no-op for a mouse click, which already focuses
  // the clicked button natively.
  useEffect(() => {
    const list = listRef.current;
    if (!list || !list.contains(document.activeElement)) return;
    tabRefs.current.get(activeTabId)?.focus();
  }, [activeTabId]);

  const scrollByOneTab = (direction: 'left' | 'right') => {
    const list = listRef.current;
    if (!list) return;
    const items = Array.from(list.children) as HTMLElement[];
    if (direction === 'right') {
      const next = items.find((item) => item.offsetLeft + item.offsetWidth > list.scrollLeft + list.clientWidth);
      if (next) list.scrollTo({ left: next.offsetLeft, behavior: 'smooth' });
    } else {
      const prev = [...items].reverse().find((item) => item.offsetLeft < list.scrollLeft);
      if (prev) list.scrollTo({ left: prev.offsetLeft, behavior: 'smooth' });
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'Home') {
      e.preventDefault();
      onTabChange(tabs[0].id);
      return;
    }
    if (e.key === 'End') {
      e.preventDefault();
      onTabChange(tabs[tabs.length - 1].id);
      return;
    }
    if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
    e.preventDefault();
    const currentIndex = tabs.findIndex((tab) => tab.id === activeTabId);
    const delta = e.key === 'ArrowRight' ? 1 : -1;
    const nextTab = tabs[(currentIndex + delta + tabs.length) % tabs.length];
    onTabChange(nextTab.id);
  };

  const showOverflowNav = canScrollLeft || canScrollRight;

  return (
    <chakra.div __css={styles.header}>
      <chakra.div ref={listRef} role="tablist" aria-label={ariaLabel} onKeyDown={handleKeyDown} __css={styles.menu}>
        {tabs.map((tab) => {
          const isActive = tab.id === activeTabId;
          return (
            <chakra.button
              key={tab.id}
              ref={(el: HTMLButtonElement | null) => {
                if (el) tabRefs.current.set(tab.id, el);
                else tabRefs.current.delete(tab.id);
              }}
              id={`${idPrefix}-tab-${tab.id}`}
              type="button"
              role="tab"
              aria-selected={isActive}
              aria-controls={`${idPrefix}-panel`}
              tabIndex={isActive ? 0 : -1}
              onClick={() => onTabChange(tab.id)}
              __css={{ ...styles.navItem, ...(isActive ? styles.navItemActive : {}) }}
            >
              {tab.label}
            </chakra.button>
          );
        })}
      </chakra.div>
      {showOverflowNav && (
        <chakra.div __css={styles.navigationIconGroup}>
          <ZimmButton
            variant="icon"
            icon="chevron-left"
            label="Previous tab"
            disabled={!canScrollLeft}
            onClick={() => scrollByOneTab('left')}
          />
          <ZimmButton
            variant="icon"
            icon="chevron-right"
            label="Next tab"
            disabled={!canScrollRight}
            onClick={() => scrollByOneTab('right')}
          />
        </chakra.div>
      )}
    </chakra.div>
  );
};

import React, { useId, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
import type { ZimmDrawerSize } from 'app/components/ui-kits/atoms/zimmDrawer';
import { ZimmTabs } from 'app/components/ui-kits/molecules/zimmTabs';
import type { ZimmTabItem } from 'app/components/ui-kits/molecules/zimmTabs';

const ZIMM_PDP_DRAWER_RECIPE = 'ZimmPdpDrawer';

export type ZimmPdpDrawerTab = ZimmTabItem & {
  content: React.ReactNode;
};

type ZimmPdpDrawerProps = {
  isOpen: boolean;
  onClose: () => void;
  size: ZimmDrawerSize;
  /** SFCC-266's EU Environmental Qualities tab, SFCC-102's Size & Fit, etc. all pass their own
   *  content component here — this organism owns none of it (SFCC-736's scope is shell only). */
  tabs: ZimmPdpDrawerTab[];
  /** Which tab is active when the drawer mounts — e.g. the tab the triggering info-link maps to.
   *  Only read on first mount; pass a `key` at the call site to force a reset on reopen with a
   *  different starting tab. */
  initialTabId?: string;
  /** No visible title exists in the tabbed header (unlike a plain-title drawer), so this is
   *  required rather than filled with placeholder copy. */
  ariaLabel: string;
};

/**
 * The SFCC-736 pdp/drawer deliverable — composes ZimmDrawer (shell) with ZimmTabs (nav header)
 * and swaps content by active tab. Renders the shell even with an empty `tabs` array (AC 11).
 *
 * @param props see ZimmPdpDrawerProps
 */
export const ZimmPdpDrawer = ({ isOpen, onClose, size, tabs, initialTabId, ariaLabel }: ZimmPdpDrawerProps) => {
  const styles = useMultiStyleConfig(ZIMM_PDP_DRAWER_RECIPE, { variant: size });
  // `initialTabId` only wins when it actually matches one of `tabs` — an id from a stale caller
  // or a typo would otherwise select no tab at all, and ZimmTabs gives every tab `tabIndex={-1}`
  // when none is active, so keyboard users could never enter the tablist.
  const initialTab = tabs.find((tab) => tab.id === initialTabId);
  const [activeTabId, setActiveTabId] = useState(initialTab?.id ?? tabs[0]?.id ?? '');
  // Shared with ZimmTabs (as `idPrefix`) so each tab's `id`/`aria-controls` and this panel's
  // `id`/`aria-labelledby` reference each other correctly — `useId()` keeps it unique even with
  // more than one tabbed drawer mounted at once (this page also mounts an untabbed ZimmDrawer).
  const idPrefix = useId();

  const activeTab = tabs.find((tab) => tab.id === activeTabId);

  return (
    <ZimmDrawer isOpen={isOpen} onClose={onClose} size={size} aria-label={ariaLabel}>
      {tabs.length > 0 && (
        <ZimmTabs
          tabs={tabs}
          activeTabId={activeTabId}
          onTabChange={setActiveTabId}
          size={size}
          ariaLabel={ariaLabel}
          idPrefix={idPrefix}
        />
      )}
      {activeTab ? (
        <chakra.div
          id={`${idPrefix}-panel`}
          role="tabpanel"
          aria-labelledby={`${idPrefix}-tab-${activeTabId}`}
          tabIndex={0}
          __css={styles.content}
        >
          {activeTab.content}
        </chakra.div>
      ) : (
        // AC 11 — zero tabs (or an activeTabId with no matching tab) still renders the shell,
        // but with no tab to relate a panel to, `role="tabpanel"`/`aria-labelledby` would
        // reference a nonexistent tab id — a plain container carries no such claim.
        <chakra.div __css={styles.content} />
      )}
    </ZimmDrawer>
  );
};

