import React, { useEffect, useState } from 'react';
import { Modal, ModalOverlay, ModalContent, useMultiStyleConfig } from '@chakra-ui/react';

const ZIMM_MODAL_RECIPE = 'ZimmModal';

type ZimmModalProps = {
  /** Whether the dialog is open. Nothing renders until this and `mounted` are both true. */
  isOpen: boolean;
  /** From the paired useZimmModal() call — false until the first client render, so the portal
   *  is never created during SSR. */
  mounted: boolean;
  /** Called on backdrop click and on Escape (both handled by Chakra's Modal). */
  onClose: () => void;
  /** Dialog panel max-width. No default — each modal type has its own Figma-specified size, so
   *  a caller-supplied value is safer than a guessed generic default. */
  maxWidth: string;
  /** id of the element that labels the dialog (aria-labelledby). */
  labelledBy: string;
  /** id of the element that describes the dialog (aria-describedby), if one exists. */
  describedBy?: string;
  children: React.ReactNode;
};

/**
 * Generic modal chrome — portal, backdrop, and an accessible dialog panel, built on Chakra's
 * Modal primitive (focus trap, initial focus, focus restore, body-scroll lock, and Escape/
 * overlay-click-to-close all come from Chakra rather than being hand-rolled). Owns none of the
 * content: a caller supplies its own form/fields as children. Public props are unchanged from
 * the previous hand-rolled implementation, so existing consumers (ZimmSubscribeModal) require
 * no changes.
 *
 * @param props see ZimmModalProps
 */
export const ZimmModal = ({
  isOpen,
  mounted,
  onClose,
  maxWidth,
  labelledBy,
  describedBy,
  children,
}: ZimmModalProps) => {
  const styles = useMultiStyleConfig(ZIMM_MODAL_RECIPE, {});
  // A React-state-backed ref, not a plain `useRef` — see the effect below for why.
  const [contentNode, setContentNode] = useState<HTMLElement | null>(null);

  /*
   * `aria-labelledby`/`aria-describedby` as plain props on `<ModalContent>` are silently
   * dropped — confirmed by reading @chakra-ui/modal's source (`chunk-XG6IELTC.mjs`'s
   * `getDialogProps`), not assumed. It unconditionally recomputes both from its own
   * `ModalHeader`/`ModalBody`-mount tracking (`headerMounted ? headerId : undefined`, same for
   * `bodyMounted`/`bodyId`) *after* spreading whatever props we pass, so ours are always
   * overwritten. Since ZimmModal's children are opaque — callers render their own title/body,
   * never Chakra's `ModalHeader`/`ModalBody` — those always compute to `undefined`, silently
   * dropping the ids this component exists to carry. This is a real Chakra 2.7 constraint, not
   * a `__css`-vs-`sx` prop-mechanism issue (that fix, applied elsewhere in ZimmDrawer, doesn't
   * apply here — `aria-labelledby` isn't a style prop). Setting the attributes directly on the
   * rendered DOM node is the only way to make them stick without restructuring every consumer's
   * children into Chakra's `ModalHeader`/`ModalBody` slots, which would be a much larger, breaking
   * change to this component's public API.
   *
   * A plain `useRef` + `useEffect(() => {...}, [isOpen, ...])` looked right but doesn't work:
   * confirmed by inspection that `ModalContent`'s dialog `<section>` mounts via Chakra's own
   * Portal, which does its own two-pass mount (an internal effect flips a "has portal target"
   * flag before the real DOM node exists) — so on `isOpen`'s *first* transition to `true`, our
   * effect fires and reads the ref before Chakra's Portal has actually attached it, and never
   * fires again since none of `[isOpen, labelledBy, describedBy]` change on Portal's own later
   * commit. A callback ref (via `useState`, not a mutable `useRef`) sidesteps this entirely: it
   * fires exactly when React actually attaches/detaches the real node, whichever commit that is,
   * and storing it in state makes the effect below re-run at that point too.
   */
  useEffect(() => {
    if (!isOpen || !contentNode) return;
    contentNode.setAttribute('aria-labelledby', labelledBy);
    if (describedBy) {
      contentNode.setAttribute('aria-describedby', describedBy);
    } else {
      contentNode.removeAttribute('aria-describedby');
    }
  }, [isOpen, contentNode, labelledBy, describedBy]);

  if (!mounted) return null;

  return (
    <Modal isOpen={isOpen} onClose={onClose} isCentered>
      <ModalOverlay __css={{ background: styles.overlay.background, zIndex: styles.overlay.zIndex }} />
      <ModalContent ref={setContentNode} __css={{ ...styles.panel, maxWidth, margin: styles.overlay.padding }}>
        {children}
      </ModalContent>
    </Modal>
  );
};

