=====use-modal-state.ts (full, new file)=====
import { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';

type UseModalStateParams = {
  /** Auto-close when the route changes. Defaults to true. */
  closeOnRouteChange?: boolean;
  /** Clear the data payload on close rather than keeping the last value. Defaults to true. */
  resetDataOnClose?: boolean;
};

type UseModalStateReturn<TData> = {
  /** Whether the dialog is currently open. */
  isOpen: boolean;
  /** The payload passed to the most recent onOpen call, or null before the first open / after a reset close. */
  data: TData | null;
  /** Opens the dialog with the given payload. */
  onOpen: (data: TData) => void;
  /** Closes the dialog. */
  onClose: () => void;
};

/**
 * Generic open/close state for any dialog (Drawer, Modal, etc.) — isOpen plus an optional data
 * payload, with onOpen(data)/onClose() handlers. Optionally auto-closes on route changes.
 * Override of the base retail-react-app hook of the same name (identical public behaviour,
 * ported to TypeScript with a generic payload type).
 *
 * @param params closeOnRouteChange / resetDataOnClose options
 * @returns open state, payload, and open/close handlers
 */
export const useModalState = <TData = unknown>({
  closeOnRouteChange = true,
  resetDataOnClose = true,
}: UseModalStateParams = {}): UseModalStateReturn<TData> => {
  const [state, setState] = useState<{ isOpen: boolean; data: TData | null }>({
    isOpen: false,
    data: null,
  });

  const { pathname } = useLocation();

  useEffect(() => {
    if (closeOnRouteChange) {
      setState((prev) => (prev.isOpen ? { isOpen: false, data: resetDataOnClose ? null : prev.data } : prev));
    }
  }, [pathname, closeOnRouteChange, resetDataOnClose]);

  return {
    isOpen: state.isOpen,
    data: state.data,
    onOpen: (data: TData) => {
      setState({ isOpen: true, data });
    },
    onClose: () => {
      setState((prev) => ({
        isOpen: false,
        data: resetDataOnClose ? null : prev.data,
      }));
    },
  };
};

