import React from 'react';
import { chakra, VStack } from '@chakra-ui/react';
import { FormattedMessage } from 'react-intl';
import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';
import { ZimmProductStyleCode } from 'app/components/ui-kits/atoms/zimmProductStyleCode';
import { isBlankRichText } from 'app/utils/richText';

export type DetailsAndCareContentProps = {
  /** The product's display name — Figma's "Product Description" section heading. */
  displayName: string;
  longDescription?: string;
  /** `c_careInstructions` — same Business-Manager-authored markup shape as `longDescription`. */
  careInstructions?: string;
  styleCode?: string;
};

/*
 * No `material` prop yet — the design (Figma node 40001889:38504) shows a "Material" section
 * between Product Description and Care, but Tim has confirmed there is no SFCC attribute for it
 * yet (`material = TBD`). Omitted entirely rather than shown empty, matching this codebase's
 * established graceful-degradation pattern (`ZimmProductDescription`/`ZimmProductStyleCode` both
 * render nothing without data) — add it back once the attribute is confirmed.
 */

/** One `{heading, body}` block, spaced per Figma's 8px heading-to-body / 64px between-sections
 *  rhythm (`overrides/app/pages/product-detail/detailsAndCareContent.css.ts`... — no co-located
 *  recipe needed here: every value is a direct `var(--zimm-*)` Chakra prop, nothing varies by
 *  variant/state, so a recipe would be pure overhead per overrideStyling.md's hierarchy). */
const Section = ({ heading, children }: { heading: React.ReactNode; children: React.ReactNode }) => (
  <VStack align="stretch" spacing="var(--zimm-scale-xs)" width="100%">
    <chakra.h2 textStyle="productNames" color="var(--zimm-color-text-default)" margin={0}>
      {heading}
    </chakra.h2>
    {children}
  </VStack>
);

/**
 * SFCC-195 — Details & Care tab content for ZimmPdpDrawer. Presentational: receives product
 * data as props (per components.md's container/presentational rule), sourced entirely from
 * SFCC attributes via `selectPdpProductInfo` — no Contentful, matching this bucket's confirmed
 * sourcing (see the plan doc's "Tab CONTENT model is mixed-source" note).
 */
export const DetailsAndCareContent = ({
  displayName,
  longDescription,
  careInstructions,
  styleCode,
}: DetailsAndCareContentProps) => {
  return (
    <VStack align="stretch" spacing="var(--zimm-scale-4xl)" width="100%">
      {!isBlankRichText(longDescription) && (
        <Section heading={displayName}>
          <ZimmProductDescription description={longDescription} />
        </Section>
      )}

      {!isBlankRichText(careInstructions) && (
        <Section heading={<FormattedMessage defaultMessage="Care" id="product_detail.details_and_care.heading.care" />}>
          <ZimmProductDescription description={careInstructions} />
        </Section>
      )}

      {/* Renders unconditionally within this stack (not nested under Care) — ZimmProductStyleCode
          already returns null with no value, so it must not also disappear just because
          c_careInstructions happens to be unpopulated for this product. */}
      <ZimmProductStyleCode value={styleCode} />
    </VStack>
  );
};

