import React from 'react';
import { chakra, VStack } from '@chakra-ui/react';
import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';

/** One PDP drawer-trigger row (Details & Care, Size & Fit, Shipping & Returns, Assistance). */
export type PdpFooterTrigger = {
  id: string;
  label: string;
};

type PdpFooterLinksProps = {
  /** Row list, in display order. Label text is resolved by the caller (product-detail/index.tsx)
   *  so it stays in sync with the same tab's label inside ZimmPdpDrawer's ZimmTabs header. */
  triggers: readonly PdpFooterTrigger[];
  /** Called with a trigger's `id` on click — the caller opens ZimmPdpDrawer at that tab. */
  onTriggerClick: (tabId: string) => void;
  findInBoutiqueLabel: string;
  onFindInBoutiqueClick: () => void;
};

/**
 * SFCC-736/195 — the PDP info column's "Find in Boutique" link and the Details & Care / Size &
 * Fit / Shipping & Returns / Assistance drawer-trigger rows, replacing the base
 * `InformationAccordion`. Figma node 40000307:13995 ("Drawer") names each row
 * `pdp/drawer-trigger` — visually accordion-styled (label + a `+` icon) but semantically a link
 * that opens ZimmPdpDrawer at that tab, not an in-place expand/collapse.
 */
export const PdpFooterLinks = ({
  triggers,
  onTriggerClick,
  findInBoutiqueLabel,
  onFindInBoutiqueClick,
}: PdpFooterLinksProps) => {
  return (
    // 28px between the Find in Boutique link and the trigger-row group, matching
    // `ZimmProductMeta`'s own `SPACE_META_ROW` — same DS measurement (Figma node
    // 40000307:14062: "Link" at y=378 ends 402, "Drawer" starts 430), same reasoning for the rem
    // literal over `var(--zimm-scale-700)` (see zimmProductMeta.css.ts's docblock: no rem-valued
    // 28px token exists yet, and substituting the raw-px alias would defeat WCAG 1.4.4 for a
    // spacing value).
    <VStack align="stretch" spacing="1.75rem" width="100%">
      <chakra.button
        type="button"
        textStyle="linkLg"
        color="var(--zimm-color-link-default)"
        textAlign="left"
        paddingY="var(--zimm-scale-2xs)"
        onClick={onFindInBoutiqueClick}
      >
        {findInBoutiqueLabel}
      </chakra.button>

      <VStack align="stretch" spacing={0}>
        {triggers.map((trigger) => (
          <chakra.button
            key={trigger.id}
            type="button"
            display="flex"
            alignItems="center"
            justifyContent="space-between"
            width="100%"
            gap="var(--zimm-scale-xs)"
            paddingY="var(--zimm-scale-xs)"
            textStyle="body2Strong"
            color="var(--zimm-color-text-default)"
            onClick={() => onTriggerClick(trigger.id)}
          >
            {trigger.label}
            <ZimmIcon type="plus" size="md" aria-hidden />
          </chakra.button>
        ))}
      </VStack>
    </VStack>
  );
};

