// Content-area horizontal inset mirrors the header's own inset (zimmTabs.css.ts) for visual
// consistency between the tab row and the content below it — the exact content-container
// padding wasn't independently redlined in the Figma pass, so this is a reasoned match rather
// than a measured value; revisit once a content-specific redline is available.
const PADDING_COMPACT_X = 'var(--zimm-scale-2xl)';
const PADDING_LARGE_X = 'var(--zimm-scale-4xl)';

export const ZimmPdpDrawer = {
  parts: ['content'],
  baseStyle: {
